/**
 * Where a note came from: written by you, imported from elsewhere, or machine-generated.
 *
 * The tree shows it **with a single icon only**, no text (docs/sidebar-ia-plan.md §3): a row already
 * carries the expand arrow, icon, title, collision time, fact badge, ingest badge, clone badge and child count;
 * two more pieces of text would turn the tree into a table. And the icon column is already there.
 *
 * Why it deserves that one glyph: when the library mixes hand-written notes, Feishu imports and sections generated by writing plans,
 * **"did I write this row or did a machine" is the one piece of information that changes how you read it** -- it decides
 * whether you trust what it says and whether you should edit it directly.
 */
import { t } from '../i18n'
const ICON: Record<string, string> = {
  obsidian: 'bx-shape-triangle',
  notion: 'bx-file',
  feishu: 'bx-paper-plane',
  apple: 'bx-notepad',
  evernote: 'bx-bookmark',
  import: 'bx-import',
  plan: 'bx-rocket',          // sections generated by a writing plan: same icon as endless writing

  // `notes.icon` (slides bx-slideshow, screen activity review bx-desktop), and in `iconOf`
  // the user icon wins, so the icon shows no difference -- **but hovering must still say where it came from**,
  // which is exactly `sourceLabel`'s job.
  slides: 'bx-slideshow',
  journey: 'bx-desktop',
}

const LABEL: Record<string, string> = {
  obsidian: 'Imported from Obsidian', notion: 'Imported from Notion', feishu: 'Imported from Feishu',
  apple: 'Imported from Apple Notes', evernote: 'Imported from Evernote', import: 'Import',
  plan: 'Generated by endless writing',
  slides: 'Slides version of this note (AI-generated; edit the note and regenerate)',
  journey: 'Screen activity digest (AI-generated)',
}

/** The icon for a source if there is one; empty string for none (written by you) -- the caller uses the default icon. */
export function sourceIcon(source?: string): string {
  return ICON[(source ?? '').trim()] ?? ''
}

/** On hover, say what this icon means; nothing for hand-written ones (no need to explain "normal"). */
export function sourceLabel(source?: string): string {
  return t(LABEL[(source ?? '').trim()] ?? '')
}
